import React, { useState } from "react";
import { useRouter } from "next/router";

const navLinks = [
  { name: "Dashboard", href: "/patient/dashboard" },
  { name: "Appointments", href: "/patient/appointments" },
  { name: "Doctors", href: "/patient/doctors" },
  { name: "Profile", href: "/patient/profile" },
];

export default function Sidebar() {
  const [open, setOpen] = useState(false);
  const router = useRouter();

  return (
    <>
      {/* Hamburger for mobile */}
      <button
        className="md:hidden p-2 m-2"
        onClick={() => setOpen((o) => !o)}
        aria-label="Toggle sidebar"
      >
        <span className="block w-6 h-0.5 bg-gray-800 mb-1" />
        <span className="block w-6 h-0.5 bg-gray-800 mb-1" />
        <span className="block w-6 h-0.5 bg-gray-800" />
      </button>
      {/* Sidebar */}
      <aside
        className={`$ {
          open ? "block" : "hidden"
        } md:block bg-white shadow h-full w-64 p-4 fixed md:static z-20`}
      >
        <nav className="flex flex-col gap-4">
          {navLinks.map((link) => (
            <button
              key={link.name}
              onClick={() => router.push(link.href)}
              className="text-left px-3 py-2 rounded hover:bg-gray-100 font-medium"
            >
              {link.name}
            </button>
          ))}
        </nav>
      </aside>
    </>
  );
} 